    trapExamples: [{ question: "「かがみ」を「かかみ」と かいた。どこが ちがう？", wrongAnswer: "ちがいは ない", trapExplanation: "てんてんの ちがいに きづかなかった。", correctAnswer: "てんてんが ない", correctExplanation: "「が」には てんてんが ある。「かかみ」では ことばに ならない。" }],
