    intro: "ことばを ならべて、ぶんを つくる れんしゅうを しよう。「は」「を」「へ」を つかって、ただしい じゅんに ならべるよ。",
    keyPoints: ["ことばを ならべて ぶんを つくる", "じゅんばんで いみが かわる", "さいごに「。」を つける"],
    sections: [
      { heading: "1. ことばを ならべて ぶんを つくる", body: "■ ならべかえて ぶんを つくる\nことば：「ぼくは」「ほんを」「よむ」\n・ぼくは ほんを よむ。\n・ほんを ぼくは よむ。（これも ぶんには なるが、ふつうは 1ばんめの ならびの ほうが つかわれる）\n\n■ きまり\nふつうの ならびは「**だれは**」「**なにを**」「**どうする**」。\n\n■ じゅんばんで いみが かわる ことも\n「いぬが ねこを おう。」と「ねこが いぬを おう。」は いみが ちがう。\n\n■ なぜ じゅんばんを かんがえるの？\nことばの じゅんばんが ちがうと、いみが かわったり、わかりにくく なったり するからです。\n\n★ ここがポイント：**だれは → なにを → どうする**の じゅんに ならべる。さいごに「**。**」。", figureId: "u120k1_042_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】「ぼくは」「りんごを」「たべる」を ならべて ぶんを つくろう\n\n【なぜ この やりかたかな】「だれは」「なにを」「どうする」の ふつうの ならびで ならべると、わかりやすい ぶんに なるから。\n\n【ステップ1】「だれは」：ぼくは\n【ステップ2】「なにを」：りんごを\n【ステップ3】「どうする」：たべる\n【ステップ4】さいごに「。」\n\n【こたえ】ぼくは りんごを たべる。\n\n【たしかめ】こえに だして よんで、いみが とおるか たしかめる。" },
      { heading: "3. よくある まちがい", body: "■ 「どうする」を さいしょに おく\n\n「たべる ぼくは りんごを」と ならべる まちがい。\n\n■ なおしかた\n・「だれは」「なにを」「どうする」の じゅんに ならべる\n・こえに だして よんで たしかめる\n\n★ ここがポイント：**だれは → なにを → どうする**。" },
      { heading: "4. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・ことばを 3つ えらんで、ぶんを つくって、おうちの 人に いってみよう\n・ことばの じゅんばんを かえると いみが かわる ぶんを さがしてみよう\n\n■ おうちの人へ\n身近な言葉（ぼく・ごはん・たべる）で並べ替え遊びをしましょう。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
