    sections: [
      { heading: "1. ひらがなで ぶんを かく", body: "■ ぶんを かく\n「きょう、ぼくは がっこうへ いきました。ともだちと あそびました。」\n\n■ ちゅうい する こと\n・「**は**」「**を**」「**へ**」を ただしく つかう\n・ぶんの おわりに「**。**」、ひと休みする ところに「**、**」\n・ちいさい「っ」「ゃ・ゅ・ょ」を わすれない\n・のばす おとを かきわすれない\n\n■ なぜ かいた あとに よむの？\nこえに だして よむと、かきまちがいや、たりない ことばに きづけるからです。\n\n★ ここがポイント：かいた あとに **こえに だして**よむ。**は・を・へ、まる・てん**を たしかめる。", figureId: "u120k1_099_a" },
      { heading: "2. やってみよう", body: "【なにを きかれているかな】「ぼくわ がっこうえ いきました」の まちがいを なおそう\n\n【なぜ この やりかたかな】は・を・へを ただしく つかうと きまって いるから。\n\n【ステップ1】「わ」は ぶんを つなぐ ことば → 「は」\n【ステップ2】「え」は どこへ → 「へ」\n【ステップ3】「ぼくは がっこうへ いきました。」\n\n【こたえ】ぼくは がっこうへ いきました。\n\n【たしかめ】こえに だして よむ。" },
      { heading: "3. よくある まちがい", body: "■ かいた あとに よまない\n\nぶんを かいて おわりに して、まちがいに きづかない まちがい。\n\n■ なおしかた\n・かいた あとで こえに だして よむ\n・まる・てん・「は・を・へ」を ゆびで たしかめる\n\n★ ここがポイント：かいた あとに **よむ**。" },
      { heading: "4. じぶんの ことばで いってみよう", body: "■ ことばに して みよう（アウトプット）\n・きょうの できごとを 3ぶん ひらがなで かいてみよう\n・かいた ぶんを こえに だして よんで、まちがいを さがしてみよう\n\n■ おうちの人へ\n書いた文章を一緒に声に出して読みましょう。\n\n★ ここがポイント：**読むだけでなく、声に出して言う・紙に書く**と、しっかり身につきます。まちがえても大丈夫。「どうしてそう思ったの？」と聞いてあげてください。" },
    ],
